  getrusage(RUSAGE_SELF, &r);

  sqlite3_snprintf(حجم(buf), buf,
    "ru_utime=%d.%06d ru_stime=%d.%06d ru_minflt=%d ru_majflt=%d", 
    (صحیح)r.ru_utime.tv_sec, (صحیح)r.ru_utime.tv_usec, 
    (صحیح)r.ru_stime.tv_sec, (صحیح)r.ru_stime.tv_usec, 
    (صحیح)r.ru_minflt, (صحیح)r.ru_majflt
  );
